UPDATE t_res_base
SET rbs_file_path = #{filePath},
    rbs_file_name = #{fileName},
    rbs_file_size = #{fileSize}
WHERE rbs_id = #{resumeId}
  AND rbs_user_id = #{userId}
  AND rbs_status = 1

UPDATE t_res_base
SET rbs_status = 0, rbs_is_default = 0
WHERE rbs_id = #{resumeId}
  AND rbs_user_id = #{userId}
  AND rbs_status = 1

